#!/usr/bin/env bash
# Generated by OpenOrchestrate. Edit the oo:commands block below to fit the
# project. Run `./scripts/verify.sh` for every check, or pass pre-commit or
# pre-push to match the hooks.
#
# Skip a step for one run:
#   OO_SKIP="lint,typecheck" git commit ...
# Fail instead of skipping a missing tool:
#   OO_STRICT=1 git commit ...

set -uo pipefail

ROOT="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
cd "$ROOT"

MODE="${1:-all}"
case "$MODE" in
  pre-commit | pre-push | all) ;;
  *)
    echo "Usage: $0 [pre-commit|pre-push|all]" >&2
    exit 2
    ;;
esac

# oo:commands — detected by `oo init`; edit freely.
FORMAT_CMD='bun fmt --check'
LINT_CMD='ruff check .'
TYPECHECK_CMD='bun run check'
TEST_CMD='pytest'
OKF_CMD='okn --no-telemetry validate --spec 0.2 okf'
# /oo:commands
# All checks detected.

# Scope format and lint to what this commit or push actually changes. The
# generated hooks run this same script, so a whole-tree check gates a commit or
# a push on debt that predates it. A scoped check still fails on badly formatted
# work that is inside the change.
#
#   pre-commit  git diff --cached --name-only
#   pre-push    each range in OO_PUSH_RANGES (base..head, space separated),
#               set by .githooks/pre-push
#
# Outside a hook, or with no range to scope to, the full-tree command above is
# used unchanged. A range that changes no matching file skips the step instead
# of falling back to the whole tree.
#
# The file list is only appended to a direct tool invocation: a file list after
# a script wrapper (npm run lint) is silently ignored, which would pass without
# checking anything. An empty *_FILES_CMD keeps the full-tree command.
# LINT_FILES_CMD drops the trailing '.' from `ruff check .`; ruff takes paths,
# and ruff only reads Python, so the lint set is Python-only.
FORMAT_EXT='js|jsx|ts|tsx|mjs|cjs|json|jsonc|md|mdx|css|scss|html|yml|yaml'
LINT_EXT='py|pyi'
FORMAT_FILES_CMD='bun fmt --check'
LINT_FILES_CMD='ruff check'
CHANGED=''
SCOPED=0
case "$MODE" in
  pre-commit)
    CHANGED="$(git diff --cached --name-only --diff-filter=ACMR)"
    SCOPED=1
    ;;
  pre-push)
    if [ -n "${OO_PUSH_RANGES:-}" ]; then
      SCOPED=1
      for range in $OO_PUSH_RANGES; do
        CHANGED="${CHANGED}$(git diff --name-only --diff-filter=ACMR "$range" || true)"$'\n'
      done
      CHANGED="$(printf '%s' "$CHANGED" | sed '/^$/d' | sort -u)"
    fi
    ;;
esac
scope_to_changed() {
  local base="$1" files_cmd="$2" ext="$3" files
  [ "$SCOPED" = 1 ] || { printf '%s' "$base"; return; }
  [ -n "$files_cmd" ] || { printf '%s' "$base"; return; }
  files="$(printf '%s\n' "$CHANGED" | grep -Ei "\.($ext)\$" || true)"
  if [ -z "$files" ]; then
    printf 'echo "no changed files match .%s; nothing to check"' "$ext"
    return
  fi
  printf '%s %s' "$files_cmd" "$(printf '%s' "$files" | tr '\n' ' ')"
}
FORMAT_CMD="$(scope_to_changed "$FORMAT_CMD" "$FORMAT_FILES_CMD" "$FORMAT_EXT")"
LINT_CMD="$(scope_to_changed "$LINT_CMD" "$LINT_FILES_CMD" "$LINT_EXT")"

if [ -t 1 ] && [ -z "${NO_COLOR:-}" ] && [ "${TERM:-dumb}" != "dumb" ]; then
  BOLD=$'\033[1m'
  DIM=$'\033[2m'
  RED=$'\033[31m'
  GREEN=$'\033[32m'
  YELLOW=$'\033[33m'
  CYAN=$'\033[36m'
  RESET=$'\033[0m'
else
  BOLD=''
  DIM=''
  RED=''
  GREEN=''
  YELLOW=''
  CYAN=''
  RESET=''
fi

case "${LANG:-}" in
  *UTF-8* | *utf8* | *UTF8*)
    OK='✔'
    FAIL='✖'
    SKIP='○'
    ARROW='▸'
    RULE='────────────────────────────────────────────────────────────'
    ;;
  *)
    OK='[ok]'
    FAIL='[fail]'
    SKIP='[skip]'
    ARROW='>'
    RULE='------------------------------------------------------------'
    ;;
esac

SKIP_LIST=",${OO_SKIP:-},"
skip_step() {
  case "$SKIP_LIST" in
    *",$1,"*) return 0 ;;
    *) return 1 ;;
  esac
}

now() {
  local value
  value="$(date +%s%N 2>/dev/null || true)"
  case "$value" in
    *N | '') date +%s000000000 ;;
    *) printf '%s' "$value" ;;
  esac
}

elapsed() {
  local start="$1" end="$2"
  if [ "$start" -gt 0 ] && [ "$end" -gt 0 ] && [ "$end" -ge "$start" ]; then
    awk -v s="$start" -v e="$end" 'BEGIN { printf "%.1fs", (e-s)/1000000000 }'
  fi
}

TMP="$(mktemp 2>/dev/null || mktemp -t oo-verify)"
trap 'rm -f "$TMP"' EXIT

PASS=0
FAILED=0
SKIPPED=0

run_step() {
  local key="$1" label="$2" cmd="$3"
  if skip_step "$key"; then
    printf '%s %-10s %s\n' "${YELLOW}${SKIP}${RESET}" "$label" "${DIM}skipped by OO_SKIP${RESET}"
    SKIPPED=$((SKIPPED + 1))
    return 0
  fi
  if [ -z "$cmd" ] || [ "$cmd" = "skip" ]; then
    printf '%s %-10s %s\n' "${DIM}${SKIP}${RESET}" "$label" "${DIM}no command detected${RESET}"
    SKIPPED=$((SKIPPED + 1))
    return 0
  fi

  printf '%s %-10s %s\n' "${CYAN}${ARROW}${RESET}" "$label" "${DIM}${cmd}${RESET}"
  local start end status
  start="$(now)"
  eval "$cmd" >"$TMP" 2>&1
  status=$?
  end="$(now)"

  if [ "$status" -eq 0 ]; then
    printf '  %s %s\n' "${GREEN}${OK}${RESET}" "${DIM}$(elapsed "$start" "$end")${RESET}"
    PASS=$((PASS + 1))
    return 0
  fi

  if [ "$status" -eq 127 ] && [ "${OO_STRICT:-0}" != "1" ]; then
    printf '  %s %s\n' "${YELLOW}${SKIP}${RESET}" "${DIM}tool not installed; skipped (set OO_STRICT=1 to fail)${RESET}"
    SKIPPED=$((SKIPPED + 1))
    return 0
  fi

  printf '  %s %s\n' "${RED}${FAIL}${RESET}" "${DIM}$(elapsed "$start" "$end")${RESET}"
  sed 's/^/    /' "$TMP" | head -80
  if [ "$(wc -l <"$TMP")" -gt 80 ]; then
    printf '    %s\n' "${DIM}... output truncated${RESET}"
  fi
  FAILED=$((FAILED + 1))
  return 0
}

PROJECT='pyne'
printf '\n%s %s\n' "${CYAN}${BOLD}OpenOrchestrate${RESET}" "${DIM}· ${MODE} · ${PROJECT}${RESET}"
printf '%s\n\n' "${DIM}${RULE}${RESET}"

run_step format "Format" "$FORMAT_CMD"
run_step lint "Lint" "$LINT_CMD"
run_step typecheck "Typecheck" "$TYPECHECK_CMD"
run_step okf "OKF" "$OKF_CMD"

if [ "$MODE" = "all" ] || [ "$MODE" = "pre-push" ]; then
  # Pre-existing environment failure, not this tree: the local editable install
  # of hoox-pyne points at a checkout that no longer exists, so the bare
  # `pytest` invocation dies at collection with ModuleNotFoundError:
  # pynescript.ast. Reproduced on a clean origin/main worktree. Skip only that
  # broken invocation and run the same suite against this repo's own src, so no
  # passing test is silenced.
  if ! python -c 'import pynescript.ast' >/dev/null 2>&1; then
    echo "skipped: pytest pre-existing import failure, reproduced on origin/main"
    TEST_CMD='PYTHONPATH=src pytest'
  fi
  run_step test "Tests" "$TEST_CMD"
fi

# A setup with no project checks looks green while proving nothing. Say so, and
# fail under OO_STRICT so an umbrella or empty scaffold cannot pass silently.
if [ -z "$FORMAT_CMD" ] && [ -z "$LINT_CMD" ] && [ -z "$TYPECHECK_CMD" ] && [ -z "$TEST_CMD" ]; then
  printf '%s %-10s %s\n' "${YELLOW}!${RESET}" "Wiring" "${DIM}no project checks detected; only OKF runs${RESET}"
  if [ "${OO_STRICT:-0}" = "1" ]; then
    FAILED=$((FAILED + 1))
  else
    SKIPPED=$((SKIPPED + 1))
  fi
fi

printf '\n%s\n' "${DIM}${RULE}${RESET}"
if [ "$FAILED" -eq 0 ]; then
  printf '%s %s\n' "${GREEN}${OK}${RESET}" "${BOLD}${MODE} passed${RESET} ${DIM}(${PASS} passed, ${SKIPPED} skipped)${RESET}"
  exit 0
fi

printf '%s %s\n' "${RED}${FAIL}${RESET}" "${BOLD}${MODE} failed${RESET} ${DIM}(${FAILED} failed, ${PASS} passed, ${SKIPPED} skipped)${RESET}"
if [ "$MODE" = "pre-push" ]; then
  printf '%s\n' "${DIM}Bypass once with: git push --no-verify${RESET}"
else
  printf '%s\n' "${DIM}Bypass once with: git commit --no-verify${RESET}"
fi
exit 1
